<template>
  <div class="route-map">
    <div class="tablist">
      <div v-for="(item,index) in tablist" :key="index" class="tab" :class="{active:currentTab===item.value}" @click="currentTab=item.value;updateData()">{{ item.label }}</div>
    </div>
    <div class="table-group">
      <div class="table-title">大小路</div>
      <div class="listLeft">
        <div v-for="(i,index) in latticeListLeft" :key="index" class="list_row">
          <div v-for="(item,j) in i" :key="j" class="list_col">
            <div :class="item==='单'||item==='大'||item==='庄'||item==='中'?'item redLeft':item==='双'||item==='小'||item==='闲'||item==='未'?'item blueLeft':item==='和'||item==='豹'?'item greenLeft':'item'">{{ item }}</div>
          </div>
        </div>
      </div>
    </div>
    <div class="table-group">
      <div class="table-title">单双路</div>
      <div class="listLeft">
        <div v-for="(i,index) in latticeListRight" :key="index" class="list_row">
          <div v-for="(item,j) in i" :key="j" class="list_col">
            <div :class="item==='单'||item==='大'||item==='庄'||item==='中'?'item redLeft':item==='双'||item==='小'||item==='闲'||item==='未'?'item blueLeft':item==='和'||item==='豹'?'item greenLeft':'item'">{{ item }}</div>
          </div>
        </div>
      </div>
    </div>

  </div>
</template>
<script>
import { getTrend } from '@/api/canada'
export default {
  name: 'RouteMap',
  data() {
    return {
      currentTab: '1',
      tablist: [{ label: '特码路单', value: '1' }, { label: '百位', value: '2' }, { label: '十位', value: '3' }, { label: '个位', value: '4' }],
      latticeListLeft: null,
      latticeListRight: null,
      latticeData: [],
      latticeDataRight: []
    }
  },
  created() {
    this.updateData()
  },
  mounted() {
  },
  methods: {
    updateData() {
      getTrend({ gametype: this.$route.query.id.substring(4, 9), type: this.currentTab }).then(res => {
        this.latticeData = res.datalist1
        this.latticeDataRight = res.datalist2
        this.latticeDataCalLeft()
        this.latticeDataCalRight()
      })
    },
    // 走势图数据排列算法
    latticeDataCalLeft() {
      const latticeListLeft = [[], [], [], [], [], []]
      const { latticeData } = this
      const arr = []
      for (let i = 0; i < 132; i++) {
        if (latticeData[i].typename) {
          arr.push(latticeData[i].typename)
        } else {
          arr.push('')
        }
      }
      arr.forEach((item, index) => {
        const i = index % 6
        latticeListLeft[i].push(item)
      })
      console.log(latticeListLeft)
      this.latticeListLeft = latticeListLeft
    },
    latticeDataCalRight() {
      const latticeListRight = [[], [], [], [], [], []]
      const { latticeDataRight } = this
      const arr = []
      for (let i = 0; i < 132; i++) {
        if (latticeDataRight[i].typename) {
          arr.push(latticeDataRight[i].typename)
        } else {
          arr.push('')
        }
      }
      arr.forEach((item, index) => {
        const i = index % 6
        latticeListRight[i].push(item)
      })
      console.log(latticeListRight)
      this.latticeListRight = latticeListRight
    }
  }
}
</script>
<style lang="scss" scoped>
.route-map {
    padding: 32px 20px;
    .tablist {
        display: flex;
        justify-content: center;
        // margin-bottom: 20px;
        background: rgba(163, 150, 241,0.12);
        border-radius: 12px;
        height: 64px;
        text-align: center;
        font-family: PingFangSC-Regular;
        font-size: 28px;
        color: rgba(255, 255, 255,0.75);
        letter-spacing: 0;
        text-align: center;
        font-weight: 400;
        .tab {
            width: 176px;
            line-height: 64px;
            cursor: pointer;
            transition: all 0.3s ease;
            &.active {
                color: #FFFFFF;
                background-image: linear-gradient(-70deg, #240BFD 0%, #B42DFF 100%);
                border-radius: 12px;
            }
        }
    }
    .table-group{
        margin-top: 40px;
        .table-title {
            // height: 64px;
            padding-left: 24px;
            font-family: PingFangSC-Semibold;
            font-size: 28px;
            color: #FFFFFF;
            letter-spacing: 0;
            line-height: 64px;
            font-weight: 600;
            background: rgba(56,58,112,0.50);
            background-image: radial-gradient(circle at 13% 0%, rgba(186,78,255,0.24) 0%, rgba(78,95,255,0.00) 71%);
            border-radius: 12px 12px 0 0;
        }
    }
    .listLeft  {
        border-left-color: #2F304D;
        border-left-style: solid;
        border-left-width: 2px;
        border-top-color: #2F304D;
        border-top-style: solid;
        border-top-width: 2px;
    }
    .list_row {
        display: flex;
        flex-grow: 1;
        .list_col {
            display: flex;
            flex-direction: column;
            flex-grow: 1;
            // border-bottom: 2px solid #3b435a;
            // border-right: 2px solid #3b435a;
            border-right-color: #2F304D;
            border-right-style: solid;
            border-right-width: 2px;
            border-bottom-color: #2F304D;
            border-bottom-style: solid;
            border-bottom-width: 2px;
            .item {
                border-radius: 50%;
                display: flex;
                justify-content: center;
                align-items: center;
                font-size: 24px;
                line-height: 24px;
                height: 30px;
                width: 30px;
            }
            .itemRight {
                height: 15px;
                width: 15px;
            }
            .itemCenter {
                height: 56px;
                width: 56px;
                line-height:56px;
                text-align: center;
                margin: 8px;
            }
            .blueLeft {
                background: #088bff;
                color: #fff;
            }
            .redLeft {
                background: #e43437;
                color: #fff;
            }
            .redCenter {
                background: #e43437;
                color: #fff;
                border-radius: 52px;
            }
            .greenLeft {
                background: #3cce8e;
                color: #000;
            }
            .blueRight {
                background: url('~@/assets/portal/blueIcon.png') no-repeat 50%;
                background-size: 100% 100%;
                height: 15px;
                width: 15px;
            }
            .redRight {
                background: url('~@/assets/portal/redIcon.png') no-repeat 50%;
                background-size: 100% 100%;
                height: 15px;
                width: 15px;
            }
            .greenRight {
                background: url(~@/assets/portal/greenIcon.png) no-repeat 50%;
                background-size: 100% 100%;
                height: 15px;
                width: 15px;
            }
        }
    }
}
</style>
